package.path='Tools/lua/?.lua;'..package.path
local json=require('ok.json')
local base='output/street-social-city-production/city-destinations-v2'
local city='output/street-social-city-production/city-art-v1'
local function read(p)local f=assert(io.open(p,'rb'));local v=json.decode(f:read('*a'));f:close();return v end
local function write(p,s)local f=assert(io.open(p,'wb'));f:write(s);f:close()end
local function esc(s)return tostring(s):gsub('&','&amp;'):gsub('<','&lt;'):gsub('>','&gt;'):gsub('"','&quot;')end
local plan,install,audit,imports=read(base..'/plan.json'),read(base..'/install.json'),read(base..'/audit.json'),read(base..'/imports.json')
local cityaudit=read(city..'/audit.json');assert(audit.status=='passed' and cityaudit.status=='passed' and install.map_sha256==audit.map_sha256 and audit.map_sha256==cityaudit.map_sha256)
assert(read(city..'/dest_verify-launcher.json').process_success,'Final independent verification must exit normally')
assert(audit.recaptured_images==0 and install.wall_edits==0 and #install.instances==30)
local zones={['campus-reading']='校園紫藤閱讀花園',['campus-library']='圖書館翻頁書藝',['campus-science']='科學星象庭院',['campus-engineering']='工程齒輪廣場',['campus-courtyard']='白鶴中庭',['campus-dorm']='宿舍獻花小熊園',['campus-administration']='行政館山景藝廊',['civic-garden']='文化中心彩陶庭園',['hotel-garden']='飯店花廊合照庭園',['riverside']='河岸帆影漫步區',['bay-garden']='海灣貝殼花園',['bay-camp']='漂流木露營入口',['residential-garden']='住宅彩蝶花園',['shopping-north']='北街花籃甜點角',['shopping-central']='中央街珍奶裝置',['shopping-south']='南街復古相機角',['station-court']='交通站旅行迎賓區',['office-plaza']='商辦街鐘稜鏡廣場',['mall-plaza']='百貨摩天輪藝術廣場'}
local ordered={};local models={};for _,q in ipairs(plan.assets)do models[q.id]=q;if not ordered[q.zone] then ordered[q.zone]={}end end
for _,q in ipairs(install.instances)do ordered[q.zone][#ordered[q.zone]+1]=q end
local svg={'<svg xmlns="http://www.w3.org/2000/svg" width="2400" height="2700" viewBox="0 0 2400 2700"><title>大學城新增景點實際保存位置</title><image href="../../../Docs/StreetSocialCity/world-terrain.svg" width="2400" height="2700"/><g font-family="sans-serif" font-size="18" font-weight="bold" text-anchor="middle">'}
for _,q in ipairs(install.instances)do local x=100+q.position_m[1]*2;local y=215+(1100-q.position_m[2])*2;svg[#svg+1]=string.format('<a href="index.html#%s" target="_top"><title>%s：%s</title><circle cx="%.2f" cy="%.2f" r="19" fill="#9b3e55" stroke="white" stroke-width="3"/><text x="%.2f" y="%.2f" fill="white">%s</text></a>',q.id,q.id,esc(q.name),x,y,x,y+6,q.id:sub(2))end
svg[#svg+1]='</g></svg>';write(base..'/landmarks-map.svg',table.concat(svg,'\n'))
local h={[=[<!doctype html><html lang="zh-Hant"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>大學城景點加法 · 30 種新 Tripo 物件</title><style>*{box-sizing:border-box}body{margin:0;background:#f7f0e5;color:#314137;font:16px/1.8 system-ui}header{background:#2e483c;color:#fff6e7;padding:40px max(24px,calc((100vw - 1400px)/2))}h1{font-size:36px;margin:0}main{max-width:1400px;margin:auto;padding:24px}section,article{background:#fff;border:1px solid #d7d4c8;border-radius:12px;padding:20px;margin:20px 0}a{color:#8b3c52}header a{color:#f8d8a4}.stats{display:flex;gap:12px;flex-wrap:wrap}.stats span{background:white;padding:14px 20px;border-radius:10px;border:1px solid #d7d4c8}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(290px,1fr));gap:16px}.grid article{margin:0}h2{font-size:23px;margin:0 0 10px}h3{font-size:19px;margin:0}table{width:100%;border-collapse:collapse;font-size:14px}td,th{padding:10px;text-align:left;border-bottom:1px solid #dedbd3;vertical-align:top}code{overflow-wrap:anywhere}small{color:#748173}.scroll{overflow:auto}.notice{background:#fff1d9;border-left:5px solid #c88c38;padding:15px}</style><header><h1>大學城 · 景點採加法</h1><p>保留原有牆面與各區個性，新增值得停留、逛和拍照的小空間。</p><a href="audit.json">原生保存檢查</a> · <a href="install.json">實際落位與配件</a> · <a href="imports.json">模型／LOD／生成來源</a> · <a href="../city-art-v1/restore_walls.json">牆面還原紀錄</a></header><main>]=]}
h[#h+1]='<div class="stats"><span>30 種全新 Tripo 模型</span><span>'..install.unique_zones..' 個主題區域</span><span>'..install.companions.total..' 個再利用休憩配件</span><span>30 處景點補光</span><span>2K PBR · 三階 LOD</span><span>本輪地圖重拍：0</span></div>'
h[#h+1]='<section><h2>保留原有特色</h2><p>上一版全城淺底與水平色帶已撤回，728 個牆面綁定恢復原有材質。交通站、文化中心、北商店街、學生宿舍與其他建物均保留既有牆面；本次新增加法沒有改牆。</p><p class="notice">依使用者要求，本輪沒有重拍地圖，也沒有把舊版截圖當成新版成果。這份報告驗證生成來源、remesh、尺寸、LOD、材質、配置、通道與保存狀態；新版整體畫面觀感尚未透過重拍驗收。</p></section><section><h2>實際保存位置</h2><p>下圖是原世界地形圖加上 Unreal 已保存座標的向量標記，並非新截圖。點選編號可查看物件資料。</p><a href="landmarks-map.svg"><img style="width:100%;max-height:900px;object-fit:contain" src="landmarks-map.svg" alt="30個景點主物件保存位置"></a></section><div class="grid">'
for zone,rows in pairs(ordered)do local names={};for _,q in ipairs(rows)do names[#names+1]=q.id..' '..q.name end;h[#h+1]='<article><h3>'..esc(zones[zone] or zone)..'</h3><p>'..esc(table.concat(names,'、'))..'</p></article>' end
h[#h+1]='</div><section><h2>30 種新生成物件</h2><p>每列對應獨立 Tripo Model 工作，既有配件、複本、換色沒有計入這 30 種。每件按真實高度等比例縮放；保形需要增加面數時，另存預算調整與修復收據，每件 LOD0 不超過 30,000 三角形。</p><div class="scroll"><table><tr><th>物件</th><th>區域與尺寸</th><th>LOD0／1／2</th><th>來源與檢查</th></tr>'
for _,q in ipairs(install.instances)do local m=models[q.id];local r=imports.assets[q.id];local numbers={};for _,n in ipairs(r.lod_triangles)do numbers[#numbers+1]=tostring(n)end
 h[#h+1]='<tr id="'..q.id..'"><td><strong>'..q.id..' '..esc(q.name)..'</strong></td><td>'..esc(zones[q.zone] or q.zone)..'<br>高度 '..m.height_m..'m<br><small>東 '..string.format('%.1f',q.position_m[1])..'／北 '..string.format('%.1f',q.position_m[2])..'</small></td><td>'..table.concat(numbers,' / ')..'</td><td><a href="'..esc(r.job_url)..'">Tripo 生成工作</a><br><a href="components/'..q.id..'/remesh/remeshed-candidate.glb">remesh 後 GLB</a> · <a href="components/'..q.id..'/remesh/remesh-report.json">檢查收據</a></td></tr>'
end
h[#h+1]='</table></div></section><section><h2>原生檢查與界線</h2><p>30 種模型全部經指定 instant-meshes-rs 執行及幾何檢查；混合四邊形寫出失敗的模型，改用同一程式的三角模式。參考拓樸修復、面數預算調整均有記錄，未聲稱原始提取結果不需修補。</p><p>保存後獨立重開，景點資產檢查 '..audit.checks..' 項通過；原有全城保留檢查 '..cityaudit.checks..' 項通過。沒有新增入口阻擋。原有固定測線訊號仍保留於全城報告，未宣稱歷史結構問題已修復。</p><p>新主物件為 110–180m 距離剔除，配件採較近剔除；沿用既有六色載具、植物變化與三語招牌。未測量目標硬體 FPS，未新增遊戲互動。</p><p>正式地圖 SHA-256：<code>'..esc(audit.map_sha256)..'</code></p></section></main></html>'
write(base..'/index.html',table.concat(h,'\n'))
write(base..'/acceptance.json',json.encode({status='passed',new_unique_tripo_models=30,themed_zones=install.unique_zones,reused_companions=install.companions.total,landmark_lights=30,wall_edits=0,recaptured_images=0,asset_checks=audit.checks,city_checks=cityaudit.checks,map_sha256=audit.map_sha256,visual_recapture='deferred at user request'}))
write(city..'/index.html','<!doctype html><html lang="zh-Hant"><meta charset="utf-8"><title>大學城景點加法更新</title><body style="font:20px/1.8 system-ui;max-width:900px;margin:70px auto;padding:24px;background:#f7f0e5;color:#314137"><h1>已撤回全城統一牆面</h1><p>原有牆面風格已還原，改用 30 種全新 Tripo 物件與分區休憩組合，增加各地特色。依指示本輪不重拍，因此舊版截圖不再展示為目前成果。</p><p><a href="../city-destinations-v2/index.html">查看新版景點配置、30種物件與原生檢查</a></p><p><a href="restore_walls.json">牆面還原紀錄</a> · <a href="audit.json">全城原生檢查</a></p></body></html>')
print('Published additive destinations, without new map captures')
